<?php

declare(strict_types=1);

namespace App\Api\Assignments;

use App\Api\Contracts\Domains\ApiSender;
use App\Assignments\Data\AssignmentResultData;
use App\Assignments\Data\AutoAssignmentChangeData;
use App\Assignments\Data\AutoAssignmentPageData;
use App\Assignments\Data\AutoAssignmentStatusData;
use App\Assignments\Data\RecordHolderData;
use App\Support\CallKey;

/**
 * The API of Assignments, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class AssignmentApi
{
    public function __construct(private ApiSender $sender) {}

    public function assignRecord(
        string $recordType,
        string $recordId,
        string $recipientType,
        string $recipientId,
        CallKey $requestKey = new CallKey(),
    ): AssignmentResultData {
        return $this->sender->send(AssignRecordPayload::from([
            'recordType' => $recordType,
            'recordId' => $recordId,
            'recipientType' => $recipientType,
            'recipientId' => $recipientId,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $records
     */
    public function configureAutoAssignment(
        string $actorType,
        string $actorId,
        string $assignableType,
        string $pool,
        array $records,
        int $size,
        int $expectedRevision,
        string|null $target,
        CallKey $requestKey = new CallKey(),
    ): AutoAssignmentChangeData {
        return $this->sender->send(ConfigureAutoAssignmentPayload::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'assignableType' => $assignableType,
            'pool' => $pool,
            'records' => $records,
            'size' => $size,
            'expectedRevision' => $expectedRevision,
            'target' => $target,
            'requestKey' => $requestKey,
        ]));
    }

    public function disableAutoAssignment(
        string $actorType,
        string $actorId,
        string $assignableType,
        int $expectedRevision,
        CallKey $requestKey = new CallKey(),
    ): AutoAssignmentChangeData {
        return $this->sender->send(DisableAutoAssignmentPayload::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'assignableType' => $assignableType,
            'expectedRevision' => $expectedRevision,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $records
     */
    public function enableAutoAssignment(
        string $actorType,
        string $actorId,
        string $assignableType,
        string $pool,
        array $records,
        int $size,
        int $expectedRevision,
        string|null $target,
        CallKey $requestKey = new CallKey(),
    ): AutoAssignmentChangeData {
        return $this->sender->send(EnableAutoAssignmentPayload::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'assignableType' => $assignableType,
            'pool' => $pool,
            'records' => $records,
            'size' => $size,
            'expectedRevision' => $expectedRevision,
            'target' => $target,
            'requestKey' => $requestKey,
        ]));
    }

    public function listAssignmentPools(
        string $assignableType,
    ): PoolList {
        return $this->sender->send(ListAssignmentPoolsPayload::from(['assignableType' => $assignableType]));
    }

    public function listAutoAssignments(
        string $actorType,
        string $actorId,
        string|null $after = null,
    ): AutoAssignmentPageData {
        return $this->sender->send(ListAutoAssignmentsPayload::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'after' => $after,
        ]));
    }

    public function reassignRecord(
        string $recordType,
        string $recordId,
        string $assignmentId,
        string $holderType,
        string $holderId,
        string $recipientType,
        string $recipientId,
        CallKey $requestKey = new CallKey(),
    ): AssignmentResultData {
        return $this->sender->send(ReassignRecordPayload::from([
            'recordType' => $recordType,
            'recordId' => $recordId,
            'assignmentId' => $assignmentId,
            'holderType' => $holderType,
            'holderId' => $holderId,
            'recipientType' => $recipientType,
            'recipientId' => $recipientId,
            'requestKey' => $requestKey,
        ]));
    }

    public function showAssignment(
        string $recordType,
        string $recordId,
    ): RecordHolderData {
        return $this->sender->send(ShowAssignmentPayload::from(['recordType' => $recordType, 'recordId' => $recordId]));
    }

    public function showAutoAssignment(
        string $actorType,
        string $actorId,
        string $assignableType,
    ): AutoAssignmentStatusData {
        return $this->sender->send(ShowAutoAssignmentPayload::from([
            'actorType' => $actorType,
            'actorId' => $actorId,
            'assignableType' => $assignableType,
        ]));
    }

    public function unassignRecord(
        string $recordType,
        string $recordId,
        string $assignmentId,
        string $holderType,
        string $holderId,
        CallKey $requestKey = new CallKey(),
    ): AssignmentResultData {
        return $this->sender->send(UnassignRecordPayload::from([
            'recordType' => $recordType,
            'recordId' => $recordId,
            'assignmentId' => $assignmentId,
            'holderType' => $holderType,
            'holderId' => $holderId,
            'requestKey' => $requestKey,
        ]));
    }
}
